/**
 * Chart colours shared by the d3 renderers.
 *
 * Every entry resolves through a design-token CSS variable, so charts follow
 * the active light/dark theme without a JavaScript colour lookup.
 */
export const CHART_COLORS = {
  primary: 'hsl(var(--foreground))',
  muted: 'hsl(var(--muted-foreground))',
  track: 'hsl(var(--muted))',
  grid: 'hsl(var(--border))',
  accent: 'hsl(var(--primary))',
  success: 'hsl(var(--success))',
  warn: 'hsl(var(--warning))',
  danger: 'hsl(var(--destructive))',
} as const

export type ChartColorName = keyof typeof CHART_COLORS

/** Resolve a semantic chart colour, falling back to the accent. */
export function chartToken(name: ChartColorName): string {
  return CHART_COLORS[name] ?? CHART_COLORS.accent
}

/** Fill for a mark that should read as positive/negative. */
export function signColor(value: number): string {
  return value >= 0 ? CHART_COLORS.success : CHART_COLORS.danger
}

export type ChartDatum = Record<string, string | number | null | undefined>

export type ChartSeries = {
  key: string
  label?: string
  color?: string
}

export type ChartSize = {
  width: number
  height: number
}

export type ChartTableColumn = {
  key: string
  label: string
  format?: (value: unknown, row: ChartDatum) => string
}

export type ChartLegendItem = {
  label: string
  color: string
  shape?: 'line' | 'square' | 'circle'
}

import type { ChartDatum, ChartSeries } from './chart-types'

/** Semantic chart palette backed by the theme-aware CSS variables in charts.module.scss. */
export const CHART_PALETTE = [
  'hsl(var(--chart-1))',
  'hsl(var(--chart-2))',
  'hsl(var(--chart-3))',
  'hsl(var(--chart-4))',
  'hsl(var(--chart-5))',
  'hsl(var(--chart-6))',
  'hsl(var(--chart-7))',
  'hsl(var(--chart-8))',
] as const

export function chartColor(index: number): string {
  return CHART_PALETTE[index % CHART_PALETTE.length]
}

export function seriesColor(series: ChartSeries[], index: number): string {
  return series[index]?.color ?? chartColor(index)
}

export function numeric(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? value : null
}

export function valueAt(datum: ChartDatum, key: string): number | null {
  return numeric(datum[key])
}

export function seriesValues(data: ChartDatum[], series: ChartSeries[]): number[] {
  const values: number[] = []
  for (const datum of data) {
    for (const item of series) {
      const value = valueAt(datum, item.key)
      if (value != null) values.push(value)
    }
  }
  return values
}

export function extentOf(values: number[]): [number, number] {
  if (!values.length) return [0, 1]
  let min = values[0]
  let max = values[0]
  for (const value of values) {
    if (value < min) min = value
    if (value > max) max = value
  }
  if (min === max) return [Math.min(0, min), max === 0 ? 1 : max]
  return [min, max]
}

export function stackedExtent(
  data: ChartDatum[],
  series: ChartSeries[],
): [number, number] {
  let max = 0
  let min = 0
  for (const datum of data) {
    let positive = 0
    let negative = 0
    for (const item of series) {
      const value = valueAt(datum, item.key) ?? 0
      if (value >= 0) positive += value
      else negative += value
    }
    max = Math.max(max, positive)
    min = Math.min(min, negative)
  }
  return [min, max]
}

export function compactNumber(value: number): string {
  return new Intl.NumberFormat(undefined, {
    notation: 'compact',
    maximumFractionDigits: 1,
  }).format(value)
}

export function formatPercent(value: number): string {
  return `${Math.round(value)}%`
}

export function easeOutCubic(t: number): number {
  return 1 - (1 - t) ** 3
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value))
}

export function buildTableRows(
  data: ChartDatum[],
  series: ChartSeries[],
): ChartDatum[] {
  return data.map((datum) => {
    const row: ChartDatum = {}
    for (const [key, value] of Object.entries(datum)) {
      if (series.some((item) => item.key === key)) {
        row[key] = value
      }
    }
    return row
  })
}

export function labelOf(series: ChartSeries[], index: number): string {
  return series[index]?.label ?? series[index]?.key ?? `Series ${index + 1}`
}

import type { ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './charts.module.scss'

/** Floating tooltip positioned inside a chart container. */
export function ChartTooltip({
  x,
  y,
  width,
  children,
  className,
}: {
  x: number
  y: number
  width: number
  children: ReactNode
  className?: string
}) {
  const flip = x > width * 0.65

  return (
    <div
      role="status"
      className={cx(styles.tooltip, className)}
      style={{
        left: flip ? undefined : x + 12,
        right: flip ? width - x + 12 : undefined,
        top: Math.max(4, y - 12),
      }}
    >
      {children}
    </div>
  )
}

import { useEffect, useState } from 'react'

import { useReducedMotion } from '~/hooks/use-reduced-motion'
import { easeOutCubic } from './chart-utils'

/**
 * Animates 0 → 1 on mount and whenever `resetKey` changes.
 * The RAF is always cancelled on unmount or reset.
 */
export function useAnimatedProgress({
  duration = 600,
  enabled = true,
  resetKey = '',
}: {
  duration?: number
  enabled?: boolean
  resetKey?: string
}): number {
  const reduced = useReducedMotion()
  const [progress, setProgress] = useState(0)
  const active = enabled && !reduced

  useEffect(() => {
    if (!active) {
      setProgress(1)
      return
    }
    let frame = 0
    let start = 0
    let finished = false

    const tick = (now: number) => {
      if (!start) start = now
      const next = Math.min(1, (now - start) / duration)
      setProgress(easeOutCubic(next))
      if (next < 1) {
        frame = requestAnimationFrame(tick)
      } else {
        finished = true
      }
    }
    frame = requestAnimationFrame(tick)

    // Embedded browsers and background tabs can throttle RAF indefinitely.
    // Guarantee the chart settles on its real values regardless.
    const fallback = window.setTimeout(() => {
      if (!finished) {
        finished = true
        setProgress(1)
      }
    }, duration + 120)

    return () => {
      cancelAnimationFrame(frame)
      window.clearTimeout(fallback)
    }
  }, [active, duration, resetKey])

  return active ? progress : 1
}

@use 'styles' as vz;

// ── Theme-aware chart palette ─────────────────────────────
// HSL triplets keep the `hsl(var(--chart-N))` contract used by chart-utils.
:global(:root) {
  --chart-1: 217 91% 46%;
  --chart-2: 160 63% 45%;
  --chart-3: 45 82% 55%;
  --chart-4: 262 83% 58%;
  --chart-5: 340 77% 50%;
  --chart-6: 199 89% 48%;
  --chart-7: 32 95% 44%;
  --chart-8: 215 16% 47%;
  --chart-label: 0 0% 100%;
}

:global(.dark) {
  --chart-1: 216 100% 72%;
  --chart-2: 150 66% 52%;
  --chart-3: 45 93% 61%;
  --chart-4: 258 90% 76%;
  --chart-5: 4 92% 69%;
  --chart-6: 199 89% 62%;
  --chart-7: 32 95% 60%;
  --chart-8: 215 20% 65%;
}

// ── Frame ─────────────────────────────────────────────────
.frame {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: vz.space(4);
  border: 1px solid vz.color('border', 0.8);
  border-radius: vz.radius('2xl');
  background: vz.color('card');
  color: vz.color('card-foreground');
  box-shadow: vz.elevation(1);
}

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: vz.space(3);
  margin-bottom: vz.space(3);
}

.header-text {
  min-width: 0;
}

.title {
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 600;
  line-height: 1.35;
}

.description {
  margin: vz.space(0.5) 0 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.5;
}

.actions {
  flex: none;
}

.plot {
  position: relative;
  width: 100%;
}

.plot-skeleton {
  width: 100%;
  height: 100%;
  border-radius: vz.radius('lg');
}

// ── Empty / error states ──────────────────────────────────
.state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  text-align: center;
}

.state-title {
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 600;
  line-height: 1.35;
}

.state-description {
  max-width: 20rem;
  margin: vz.space(1) 0 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.5;
}

// ── Legend ────────────────────────────────────────────────
.legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: vz.space(1.5) vz.space(4);
  margin: vz.space(3) 0 0;
  padding: 0;
  list-style: none;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: vz.space(1.5);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
}

.legend-swatch {
  display: inline-block;
  flex: none;
}

.legend-line {
  width: vz.space(4);
  height: 2px;
  border-radius: vz.radius('full');
}

.legend-circle {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: vz.radius('full');
}

.legend-square {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: vz.radius('xs');
}

// ── Data table ────────────────────────────────────────────
.data-details {
  margin-top: vz.space(3);
  padding-top: vz.space(2);
  border-top: 1px solid vz.color('border');
}

.data-summary {
  cursor: pointer;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  font-weight: 500;

  @include vz.hover {
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 2px, 0.6);
}

.data-scroll {
  max-height: 16rem;
  margin-top: vz.space(2);
  overflow: auto;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  color: vz.color('foreground');
  font-size: vz.font-size('xs');
  text-align: left;
}

.data-caption {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border-width: 0;
}

.data-table th,
.data-table td {
  padding: vz.space(1.5) vz.space(2);
  border-bottom: 1px solid vz.color('border', 0.6);
}

.data-table th {
  position: sticky;
  top: 0;
  background: vz.color('card');
  border-bottom-color: vz.color('border');
  color: vz.color('muted-foreground');
  font-weight: 500;
}

.data-table td {
  font-variant-numeric: tabular-nums;
}

.data-table tbody tr:last-child td {
  border-bottom: 0;
}

// ── Tooltip ───────────────────────────────────────────────
.tooltip {
  position: absolute;
  z-index: 20;
  max-width: 12rem;
  padding: vz.space(1.5) vz.space(2.5);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('popover');
  color: vz.color('popover-foreground');
  box-shadow: vz.elevation(2);
  font-size: vz.font-size('xs');
  line-height: 1.4;
  pointer-events: none;
}

.tooltip-title {
  margin: 0;
  color: vz.color('foreground');
  font-weight: 600;
}

.tooltip-row {
  display: flex;
  align-items: center;
  gap: vz.space(1.5);
  margin: vz.space(0.5) 0 0;
  color: vz.color('muted-foreground');
}

.tooltip-value {
  color: vz.color('foreground');
  font-variant-numeric: tabular-nums;
  font-weight: 500;
}

.tooltip-percent {
  margin-left: vz.space(1);
}

.tooltip-dot {
  display: inline-block;
  flex: none;
  width: 0.375rem;
  height: 0.375rem;
  border-radius: vz.radius('full');
}

// ── SVG shared ────────────────────────────────────────────
.canvas {
  overflow: visible;
  outline: none;

  @include vz.focus-ring(2px, 2px, 0.5);
}

.tick {
  fill: vz.color('muted-foreground');
  font-size: 10px;
}

.tick-numeric {
  fill: vz.color('muted-foreground');
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}

.label-on-mark {
  fill: hsl(var(--chart-label));
  font-size: 10px;
  font-weight: 500;
  pointer-events: none;
}

.label-on-mark-muted {
  fill: hsl(var(--chart-label) / 80%);
  font-size: 9px;
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}

.center-value {
  fill: vz.color('foreground');
  font-size: vz.font-size('lg');
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}

.center-caption {
  fill: vz.color('muted-foreground');
  font-size: 10px;
}

.grid-line {
  stroke: vz.color('border');
}

.cursor-line {
  stroke: vz.color('muted-foreground');
  opacity: 0.5;
}

.hit {
  cursor: pointer;
}

.fade {
  transition: opacity vz.duration('fast') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.fade-fill {
  transition: fill-opacity vz.duration('fast') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.fluid {
  width: 100%;
}

// ── Heatmap scale ─────────────────────────────────────────
.scale-legend {
  display: flex;
  align-items: center;
  gap: vz.space(2);
  margin-top: vz.space(2);
  color: vz.color('muted-foreground');
  font-size: 10px;
}

.scale-label {
  font-variant-numeric: tabular-nums;
}

.scale-bar {
  flex: 1;
  height: 0.375rem;
  border-radius: vz.radius('full');
}
